package packages_1;

import java.util.Scanner;

public class Task_2_2 {
// Even numbers in range using while loop
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int i=1;
		while(i<=30) {
			if(i%2==0) {
				System.out.println(i);
			}
			i++;
		}
	}

}
